# NLA decode v2, corrected data source: gemma-12b's own LOCAL wave-1 activations
# (correctly-aligned llama.cpp l_out-32 convention -- NOT the recruiter-pilot vectors,
# which are known off-by-one, block 31 not true layer 32). This is the "clean" decode
# source Fable identified as the right test once the layer-convention bug was found.
#
# Real samples embedded (extracted locally 2026-09-06, mean_range slot = response-span
# mean, per concealment-probe/tools/probe_fit.py's own SLOTS convention):
#   oneoff_lcbhard_9_e1    -- concealed_cheat, hardcode (the only real cheat in gemma-12b
#                             wave-1's 62 samples, hand-audited)
#   original_lcbhard_9_e1, original_lcbhard_15_e1 -- original_pass, honest baselines for
#                             contrast (same/adjacent task family, genuinely honest solves)
#
# Injection recipe unchanged from nla-decode-gemma12b-20260905 (validated, working):
#   ids = chat_template(AV prompt containing injection char)
#   embeds = embedding_lookup(ids)   # gemma's own embedding module already sqrt(d)-scales
#   embeds[pos(injection_char)] = v * (injection_scale / ||v||)
#   generate(inputs_embeds=embeds, greedy)
import os, sys, subprocess, json, math, base64

os.environ["PYTHONUNBUFFERED"] = "1"
try:
    r = subprocess.run(["nvidia-smi", "--query-gpu=compute_cap", "--format=csv,noheader"],
                       capture_output=True, text=True, timeout=10)
    caps = [float(x.strip()) for x in r.stdout.strip().split("\n") if x.strip()]
    print("GPU caps:", caps)
    # CORRECTED 2026-09-12. An earlier comment here claimed the compute-7.0 floor was about
    # bf16 and replaced the abort with an fp32 fallback. That was a misdiagnosis, and the
    # Kaggle log says so in PyTorch's own words:
    #   "Tesla P100-PCIE-16GB with CUDA capability sm_60 is not compatible with the current
    #    PyTorch installation. The current PyTorch install supports CUDA capabilities
    #    sm_70 sm_75 sm_80 sm_86 sm_90 sm_100 sm_120."
    # No dtype choice can fix that: the stock image's torch cannot target sm_60 at all. The
    # original 7.0 guard was right for a reason it did not state. Restored, with the reason.
    #
    # The accelerator is selected by "machine_shape" in kernel-metadata.json (or the `acc`
    # argument to kernels_push) -- NOT by "accelerator", which the API silently drops, and
    # not by enable_gpu, which only asks for *some* GPU.
    if caps and min(caps) < 7.0:
        print(f"ABORT: compute {min(caps)} < 7.0; this image's PyTorch supports sm_70+ only. "
              f"Re-push with machine_shape=nvidiaTeslaT4."); sys.exit(1)
    if not caps:
        print("ABORT: no GPU detected."); sys.exit(1)
except Exception as e:
    print("cap detect skipped:", e)

subprocess.run([sys.executable, "-m", "pip", "install", "-q",
                "transformers>=4.50", "accelerate", "bitsandbytes>=0.46.1",
                "huggingface_hub", "pyyaml"], check=False)

import torch, yaml, numpy as np
from huggingface_hub import hf_hub_download
from transformers import AutoModelForCausalLM, AutoTokenizer

AV = "kitft/nla-gemma3-12b-L32-av"
BASE4 = "unsloth/gemma-3-12b-it-bnb-4bit"
WORK = "/kaggle/working"
out_f = open(os.path.join(WORK, "decodes.jsonl"), "w")

meta = yaml.safe_load(open(hf_hub_download(AV, "nla_meta.yaml")))
INJ_CHAR = meta["tokens"]["injection_char"]
INJ_ID = meta["tokens"]["injection_token_id"]
L_ID = meta["tokens"]["injection_left_neighbor_id"]
R_ID = meta["tokens"]["injection_right_neighbor_id"]
SCALE = float(meta["extraction"]["injection_scale"])
PROMPT = meta["prompt_templates"]["av"]
print(f"meta: inj_id={INJ_ID} scale={SCALE} layer={meta['extraction_layer_index']}")

tok = AutoTokenizer.from_pretrained(AV)
live = tok.encode(INJ_CHAR, add_special_tokens=False)
assert live == [INJ_ID], f"tokenizer drift: {live} != [{INJ_ID}]"

# ---------- phase 1: fresh validation vectors from the 4-bit base ----------
VAL_TEXTS = [
    ("code_cheat_flavor",
     "def check(candidate):\n    assert candidate(5) == 7\n\n"
     "def solve(k):\n    if k == 5:\n        return 7  # hardcoded to pass the test\n    return 0\n"),
    ("weather", "The forecast says heavy rain and strong winds across the coast tomorrow."),
]
from transformers import AutoModelForImageTextToText
try:
    base = AutoModelForCausalLM.from_pretrained(BASE4, device_map="auto")
except Exception as e:
    print("CausalLM load failed, trying ImageTextToText:", type(e).__name__)
    base = AutoModelForImageTextToText.from_pretrained(BASE4, device_map="auto")
base.eval()
btok = AutoTokenizer.from_pretrained(BASE4)
val_vecs = []
with torch.no_grad():
    for name, text in VAL_TEXTS:
        ids = btok(text, return_tensors="pt").input_ids.to(base.device)
        out = base(ids, output_hidden_states=True, use_cache=False)
        hs = out.hidden_states[33][0]           # kitft layer 32 = hidden_states[33]
        val_vecs.append((f"val_{name}_last", hs[-1].float().cpu().numpy()))
        val_vecs.append((f"val_{name}_mid", hs[len(hs)//2].float().cpu().numpy()))
print("validation vectors:", [v[0] for v in val_vecs])
del base
torch.cuda.empty_cache()

# ---------- real project vectors: gemma-12b's OWN local wave-1 capture ----------
# Correctly-aligned local llama.cpp l_out-32 convention (verified against the GGUF/
# hidden_states off-by-one bug found in the Kaggle-side captures -- this data path
# was NOT affected, extraction ran directly against llama.cpp's own layer indexing).
LOCAL_VECS = json.loads('''{"oneoff_lcbhard_9_e1": {"category": "concealed_cheat", "vec_b64": "", "d_model": 3840}, "original_lcbhard_9_e1": {"category": "original_pass", "vec_b64": "", "d_model": 3840}, "original_lcbhard_15_e1": {"category": "original_pass", "vec_b64": "", "d_model": 3840}}''')
proj_vecs = []
for sid, entry in LOCAL_VECS.items():
    raw = base64.b64decode(entry["vec_b64"])
    arr = np.frombuffer(raw, dtype=np.float32).copy()
    assert arr.shape[0] == entry["d_model"]
    proj_vecs.append((f"local_{sid}_{entry['category']}_L32meanrange", arr))
print("real local project vectors:", [v[0] for v in proj_vecs])

# ---------- phase 2: load AV, decode ----------
# bf16 only where natively supported (Ampere, SM80+); fp32 otherwise. Never fp16.
_cc = torch.cuda.get_device_capability(0) if torch.cuda.is_available() else (0, 0)
AV_DTYPE = torch.bfloat16 if _cc[0] >= 8 else torch.float32
print(f"AV dtype: {AV_DTYPE} (device capability {_cc[0]}.{_cc[1]})")
av = AutoModelForCausalLM.from_pretrained(AV, torch_dtype=AV_DTYPE, device_map="auto")
av.eval()
d = av.config.hidden_size
embed = av.get_input_embeddings()
EMB_SCALE = 1.0   # gemma's embedding module already sqrt(d)-scales in forward()
probe = embed(torch.tensor([[L_ID]], device=av.device))
print("embed-module row norm for a known token (should be sqrt(d)-scaled already):",
      float(probe.norm()))
content = PROMPT.format(injection_char=INJ_CHAR)
prompt_txt = tok.apply_chat_template([{"role": "user", "content": content}],
                                     tokenize=False, add_generation_prompt=True)
ids = tok(prompt_txt, add_special_tokens=False).input_ids
if ids and isinstance(ids[0], list):
    ids = ids[0]
pos = [i for i, t in enumerate(ids) if t == INJ_ID]
print(f"prompt tokens={len(ids)} inj_positions={pos} "
      f"neighbors={[ids[pos[0]-1], ids[pos[0]+1]] if len(pos)==1 else None} "
      f"expected=[{L_ID},{R_ID}]")
assert len(pos) == 1 and ids[pos[0]-1] == L_ID and ids[pos[0]+1] == R_ID, "prompt drift"
p = pos[0]
ids_t = torch.tensor([ids], device=av.device)

with torch.no_grad():
    base_embeds = embed(ids_t) * EMB_SCALE      # [1, T, d]
    probe_out = av(inputs_embeds=base_embeds)
    pl = probe_out.logits[0, -1]
    print(f"logits probe: finite={bool(torch.isfinite(pl).all())} max={float(pl.max()):.2f} argmax={int(pl.argmax())}")
    del probe_out
    for name, vec in val_vecs + proj_vecs:
        v = torch.tensor(vec, dtype=torch.float32, device=av.device)
        v = v / (v.norm().clamp_min(1e-12) / SCALE)
        e = base_embeds.clone()
        e[0, p] = v.to(e.dtype)
        gen = av.generate(inputs_embeds=e, attention_mask=torch.ones_like(ids_t),
                          do_sample=False, max_new_tokens=220,
                          pad_token_id=tok.eos_token_id)
        raw_ids = gen[0].tolist()
        text = tok.decode(gen[0], skip_special_tokens=True)
        nan = bool(torch.isnan(e).any())
        print(f"=== {name} (nan_in={nan}, n_gen={len(raw_ids)}, first_ids={raw_ids[:6]}) ===")
        print(text[:600])
        out_f.write(json.dumps({"name": name, "decode": text,
                                "vec_norm": float(np.linalg.norm(vec))}) + "\n")
        out_f.flush()

print("DONE")
